/* imp_objetos_schema: */
CREATE SCHEMA IF NOT EXISTS "app";

CREATE TYPE "app"."status" AS ENUM ('ativo', 'inativo', 'it''s pending');

CREATE DOMAIN "app"."cpf" AS varchar(14) DEFAULT '000.000.000-00' NOT NULL CHECK (VALUE ~ '^[0-9.-]+$');

CREATE DOMAIN "positivo" AS integer CHECK (VALUE > 0);

CREATE SEQUENCE "app"."seq_usuario" INCREMENT BY 5 START WITH 100 MINVALUE 1 MAXVALUE 99999 CYCLE;

CREATE SEQUENCE "seq_simples";

CREATE SEQUENCE "seq_neg" INCREMENT BY -1;

CREATE TABLE "app"."usuario" (
    "id" integer PRIMARY KEY,
    "nome" text NOT NULL,
    "situacao" app.status DEFAULT 'ativo'
);

CREATE TABLE "app"."perfil" (
    "id" integer PRIMARY KEY,
    "usuario_id" integer
);

ALTER TABLE "app"."perfil" ADD CONSTRAINT "FK_perfil_2"
    FOREIGN KEY (usuario_id)
    REFERENCES "app"."usuario" (id);

CREATE INDEX "idx_usuario_nome" ON "app"."usuario" ("nome");

CREATE UNIQUE INDEX "ux_usuario_lower" ON "app"."usuario" USING btree ("id");

CREATE INDEX "idx_perfil_1" ON "app"."perfil" ("usuario_id") WHERE usuario_id IS NOT NULL;

CREATE OR REPLACE FUNCTION "app"."soma"(a integer, b numeric(10,2) DEFAULT 0) RETURNS numeric AS $$

DECLARE
  r numeric;
BEGIN
  -- comentario no corpo; com ponto e virgula
  r := a + b; /* outro */
  ALTER TABLE app.usuario ADD CONSTRAINT nao_deve_criar CHECK (id > 0);
  RETURN r;
END;

$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION "app"."trg_audit"() RETURNS trigger AS $$

BEGIN
  INSERT INTO log VALUES (NEW.id);
  RETURN NEW;
END;

$$ LANGUAGE plpgsql;

CREATE OR REPLACE PROCEDURE "app"."limpar"(IN dias integer) AS $$

  DELETE FROM app.usuario WHERE id < dias;

$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION "app"."velha"() RETURNS integer AS $$

$$ LANGUAGE sql;

CREATE VIEW "app"."v_usuario" AS
SELECT id, nome FROM app.usuario WHERE situacao = 'ativo'
;

CREATE VIEW "v_perfil" AS
SELECT p.id, u.nome FROM app.perfil p JOIN app.usuario u ON u.id = p.usuario_id
;

CREATE MATERIALIZED VIEW "app"."mv_resumo" AS
SELECT count(*) AS total FROM app.usuario
;

CREATE TRIGGER "trg_usuario_audit" AFTER INSERT OR UPDATE OF NOME ON "app"."usuario" FOR EACH ROW WHEN (NEW.nome IS NOT NULL) EXECUTE FUNCTION app.trg_audit();

CREATE TRIGGER "trg_stmt" BEFORE DELETE ON "app"."perfil" FOR EACH STATEMENT EXECUTE FUNCTION app.limpar(1);

CREATE TRIGGER "trg_c" AFTER INSERT ON "app"."perfil" FOR EACH ROW EXECUTE FUNCTION app.trg_audit();

